// WAV/MP3 playback and the manifest generated by scripts/generate_audio.py.
let el = null;
let stopHook = null;

export const hasAudio = (phrase) => Boolean(phrase?.audio?.src);

export async function loadManifest() {
  const response = await fetch(new URL('assets/audio/manifest.json', document.baseURI), { cache: 'no-store' });
  if (!response.ok) throw new Error('音声の一覧を読み込めませんでした。');
  const manifest = await response.json();
  if (manifest.version !== 1 || !manifest.profiles) throw new Error('音声の一覧の形式が違います。');
  return manifest;
}

export function hasRange(profile, phrases) {
  return Boolean(profile?.src && phrases.length && phrases.every((p) => {
    const part = profile.phrases?.[p.id];
    return part && part.kanji === p.kanji && part.yomi === p.yomi.join('') &&
      Number.isFinite(part.start) && Number.isFinite(part.end) && part.start >= 0 && part.end > part.start;
  }));
}

export function hasTitle(profile, title) {
  const part = profile?.title;
  return Boolean(part?.src && Number.isFinite(part.start) && Number.isFinite(part.end) &&
    part.start >= 0 && part.end > part.start &&
    (!title || (part.kanji === title.kanji && part.yomi === title.yomi.join(''))));
}

// Cancellation resolves false; file/decode/playback errors reject with a visible message.
function playClip({ src, start = 0, end = null }, onTime) {
  stop();
  el ??= Object.assign(new Audio(), { preload: 'auto' });
  const a = el;
  return new Promise((resolve, reject) => {
    let settled = false;
    const timeout = setTimeout(() => finish(false, new Error('音声の読み込みがタイムアウトしました。')), 15000);
    function finish(ok, error) {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      a.pause();
      a.removeEventListener('loadedmetadata', begin);
      a.removeEventListener('timeupdate', update);
      a.removeEventListener('ended', ended);
      a.removeEventListener('error', failed);
      if (stopHook === cancel) stopHook = null;
      error ? reject(error) : resolve(ok);
    }
    const cancel = () => finish(false);
    const update = () => {
      onTime?.(a.currentTime, a.duration);
      if (end != null && a.currentTime >= end) finish(true);
    };
    const ended = () => finish(true);
    const failed = () => finish(false, new Error('音声を再生できませんでした。ファイルと音声形式を確認してください。'));
    function begin() {
      if (settled) return;
      if (!Number.isFinite(a.duration) || start >= a.duration || (end != null && end > a.duration + 0.05)) {
        finish(false, new Error('音声の長さと再生区間が一致しません。'));
        return;
      }
      a.currentTime = start;
      a.play().then(() => { if (!settled) clearTimeout(timeout); }).catch(() => {
        finish(false, new Error('音声を開始できませんでした。「読む」を押して再度お試しください。'));
      });
    }
    stopHook = cancel;
    a.addEventListener('loadedmetadata', begin, { once: true });
    a.addEventListener('timeupdate', update);
    a.addEventListener('ended', ended);
    a.addEventListener('error', failed);
    // Reset the resource even when reusing the same URL, so readiness is never stale.
    a.src = new URL(src, document.baseURI).href;
    a.load();
  });
}

export function playPhrase(phrase, onProgress) {
  if (!hasAudio(phrase)) return Promise.resolve(false);
  const clip = phrase.audio;
  return playClip(clip, (time, duration) => {
    const start = clip.start ?? 0;
    const end = clip.end ?? duration;
    onProgress?.(Math.min(1, Math.max(0, (time - start) / (end - start))));
  });
}

// Play the merged WAV once, avoiding pauses/seeks between phrases.
export function playRange(profile, phrases, onPosition, { includeTitle = false } = {}) {
  if (!hasRange(profile, phrases)) return Promise.reject(new Error('この範囲の音声はまだありません。'));
  const segments = phrases.map((p) => profile.phrases[p.id]);
  const title = includeTitle && phrases[0].id === 1 && hasTitle(profile) &&
    profile.title.end <= segments[0].start + 1e-6 ? profile.title : null;
  const speechEnd = segments.at(-1).end;
  // Let only the end of the complete recording ring out. A partial stage must
  // stop at its boundary so the next stage's spoken words are never included.
  const end = Number.isFinite(profile.speechEndSeconds) && Number.isFinite(profile.durationSeconds) &&
    Math.abs(speechEnd - profile.speechEndSeconds) < 1e-6 && profile.durationSeconds >= speechEnd
    ? profile.durationSeconds : speechEnd;
  let index = 0;
  onPosition?.(title ? -1 : 0, 0);
  return playClip({ src: profile.src, start: title?.start ?? segments[0].start, end }, (time) => {
    if (title && time < segments[0].start) {
      onPosition?.(-1, Math.min(1, Math.max(0, (time - title.start) / (title.end - title.start))));
      return;
    }
    while (index < segments.length - 1 && time >= segments[index + 1].start) index++;
    const part = segments[index];
    onPosition?.(index, Math.min(1, Math.max(0, (time - part.start) / (part.end - part.start))));
  });
}

export function stop() {
  stopHook?.();
}
